package ai.lmctl.lmaws;
import io.lmctl.lmcode.Json;
import java.nio.file.*;import java.nio.channels.*;import java.time.Instant;import java.util.*;

/** Durable, explicit-run lifecycle for Lambda scenarios 03-06. */
final class ServerlessRun implements AutoCloseable {
  final AwsBackend backend; final CostLedger cost; final String run,domain; final Path path; final Map<String,String> state=new LinkedHashMap<>(); private final FileChannel channel; private final FileLock lock;
  ServerlessRun(AwsBackend b,CostLedger c,String run,String domain,String file){if(!run.matches("[a-z0-9]{1,24}"))throw new IllegalArgumentException("invalid run id");if(domain==null||domain.isBlank())throw new IllegalArgumentException("domain required");backend=b;cost=c;this.run=run;this.domain=domain;path=Path.of(file).toAbsolutePath().normalize();try{Files.createDirectories(path.getParent());channel=FileChannel.open(path.resolveSibling(path.getFileName()+".lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE);lock=channel.tryLock();if(lock==null)throw new IllegalStateException("serverless run already active");if(Files.exists(path)){Object x=Json.parse(Files.readString(path));for(var e:Json.object(x).entrySet())state.put(e.getKey(),String.valueOf(e.getValue()));if(!run.equals(state.get("run_id"))||!String.valueOf(b.isDemo()).equals(state.get("demo")))throw new IllegalArgumentException("serverless state run/mode mismatch");}else{state.put("run_id",run);state.put("domain",domain);state.put("demo",String.valueOf(b.isDemo()));persist();}}catch(Exception e){throw new IllegalStateException("cannot open serverless state",e);}}
  private void persist(){try{Files.writeString(path,Jsons.encodeRaw(state),StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING); }catch(Exception e){throw new IllegalStateException("cannot persist serverless state",e);}}
  synchronized Map<String,String> step(String op,String args){if(!backend.isDemo())throw new IllegalStateException("serverless live deployment awaits explicit Lead authorization");if("up".equals(op)){state.put("lambda","lmaws_"+run+"_fn");state.put("table","lmaws_"+run+"_table");state.put("bucket","lmaws-"+run+"-report");state.put("rule","lmaws_"+run+"_rule");state.put("status","up");persist();}else if("down".equals(op)){state.put("status","down");persist();}else if(!Set.of("status","up","down").contains(op))throw new IllegalArgumentException("unknown serverless operation");return summary();}
  synchronized Map<String,String> summary(){var m=new LinkedHashMap<String,String>();m.put("run_id",run);m.put("status",state.getOrDefault("status","down"));m.put("lambda",state.getOrDefault("lambda",""));m.put("table",state.getOrDefault("table",""));m.put("bucket",state.getOrDefault("bucket",""));m.put("rule",state.getOrDefault("rule",""));m.put("estimated_cost_usd",backend.isDemo()?"0.00":"0.00");return m;}
  synchronized List<Map<String,String>> leftovers(){return "up".equals(state.get("status"))?List.of(summary()):List.of();}
  synchronized Map<String,String> down(){state.put("status","down");persist();return summary();}
  public void close(){try{lock.release();channel.close();}catch(Exception ignored){}}
}
